import React from 'react';
import { Link } from 'react-router-dom';
import './.css';

function Home() {
  const navLinks = [
    'All', 'Electronics', 'Fashion', 'Home & Kitchen', 'Today\'s Deals', 'Customer Service', 'Registry', 'Gift Cards'
  ];

  return (
    <div className="home-page">
      {/* Secondary Sub-Navbar (Like Amazon's category strip) */}
      <div className="home-sub-navbar">
        <div className="sub-nav-links">
          {navLinks.map((link, idx) => (
            <span key={idx} className="sub-nav-item">{link}</span>
          ))}
        </div>
        <div className="sub-nav-promo">
          <span>Great Indian Festival | Shop early deals now &gt;</span>
        </div>
      </div>

      {/* Large Orange Promotional Hero Banner */}
      <div className="home-hero-banner">
        <div className="hero-banner-content">
          <span className="sale-tag">Sale is live</span>
          <h1>Starting ₹49</h1>
          <h2>Home, kitchen, toys & outdoors</h2>
          <Link to="/products" className="hero-action-btn">
            Return to all deals &gt;
          </Link>
        </div>
      </div>
    </div>
  );
}

export default Home;
